def merge_sorted_streams(*streams):
    def merge_key(key, stream):
        for k, _ in stream:
            if k > key:
                return (key, stream)
        return (key, stream)

    result = []
    for stream in streams:
        for key, value in stream:
            if not result or merge_key(key, stream) != result[-1]:
                result.append((key, value))
    return (tuple(sorted(result, key=merge_key)) if result else ())
